const yesterdayStats = $('Yesterday\'s Article Stats').item.json[0] || {};
const topArticles = $('Top 5 Articles (24h)').all().map(item => item.json);
const subscribers = $('Newsletter Subscriber Stats').item.json[0] || {};
const categories = $('Category Performance (7d)').all().map(item => item.json);
const social = $('Social Media Performance (7d)').all().map(item => item.json);
const aiStats = $('AI Processing Stats (7d)').item.json[0] || {};

const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000);
const dateStr = yesterday.toISOString().split('T')[0];

// Calculate key metrics
const metrics = {
  date: dateStr,
  articles: {
    published_yesterday: yesterdayStats.articles_published || 0,
    total_views_yesterday: yesterdayStats.total_views || 0,
    avg_views_per_article: Math.round(yesterdayStats.avg_views || 0),
    top_performers: topArticles
  },
  subscribers: {
    total: subscribers.total_subscribers || 0,
    verified: subscribers.verified_subscribers || 0,
    new_yesterday: subscribers.new_yesterday || 0,
    growth_rate: subscribers.total_subscribers > 0 
      ? ((subscribers.new_yesterday / subscribers.total_subscribers) * 100).toFixed(2) + '%'
      : '0%'
  },
  categories: categories,
  social_media: social,
  ai_processing: {
    total_processed_7d: aiStats.total_processed || 0,
    successful: aiStats.successful || 0,
    rejected: aiStats.rejected || 0,
    success_rate: aiStats.total_processed > 0
      ? ((aiStats.successful / aiStats.total_processed) * 100).toFixed(1) + '%'
      : '0%',
    avg_processing_time: Math.round(aiStats.avg_processing_time_seconds || 0) + 's'
  }
};

// Health check
const health = {
  status: 'healthy',
  warnings: [],
  errors: []
};

// Check for issues
if (metrics.articles.published_yesterday === 0) {
  health.warnings.push('No articles published yesterday');
  health.status = 'warning';
}

if (metrics.articles.avg_views_per_article < 10 && metrics.articles.published_yesterday > 0) {
  health.warnings.push('Low average views per article');
}

if (parseFloat(metrics.ai_processing.success_rate) < 70) {
  health.errors.push('AI processing success rate below 70%');
  health.status = 'error';
}

if (metrics.subscribers.new_yesterday === 0) {
  health.warnings.push('No new subscribers yesterday');
  if (health.status === 'healthy') health.status = 'warning';
}

return [{
  json: {
    metrics: metrics,
    health: health,
    generated_at: new Date().toISOString()
  }
}];

const data = $input.item.json;
const metrics = data.metrics;
const health = data.health;

// Build text report
const report = `
📊 HSE News - Daily Analytics Report
${metrics.date}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

📰 ARTICLES (Yesterday)
• Published: ${metrics.articles.published_yesterday}
• Total Views: ${metrics.articles.total_views_yesterday}
• Avg Views/Article: ${metrics.articles.avg_views_per_article}

🏆 TOP PERFORMERS (24h)
${metrics.articles.top_performers.map((a, i) => 
  `${i + 1}. ${a.title} (${a.views_count} views)`
).join('\n')}

📧 NEWSLETTER SUBSCRIBERS
• Total Active: ${metrics.subscribers.total}
• Verified: ${metrics.subscribers.verified}
• New Yesterday: ${metrics.subscribers.new_yesterday}
• Growth Rate: ${metrics.subscribers.growth_rate}

📂 CATEGORY PERFORMANCE (7 days)
${metrics.categories.map(c => 
  `• ${c.category}: ${c.article_count} articles, ${c.total_views} views`
).join('\n')}

📱 SOCIAL MEDIA (7 days)
${metrics.social_media.map(s => 
  `• ${s.platform.toUpperCase()}: ${s.successful_posts}/${s.posts_count} posted`
).join('\n')}

🤖 AI PROCESSING (7 days)
• Total Processed: ${metrics.ai_processing.total_processed_7d}
• Success Rate: ${metrics.ai_processing.success_rate}
• Avg Processing Time: ${metrics.ai_processing.avg_processing_time}
• Rejected: ${metrics.ai_processing.rejected}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
🏥 SYSTEM HEALTH: ${health.status.toUpperCase()}

${health.warnings.length > 0 ? '⚠️ WARNINGS:\n' + health.warnings.map(w => `• ${w}`).join('\n') : ''}
${health.errors.length > 0 ? '❌ ERRORS:\n' + health.errors.map(e => `• ${e}`).join('\n') : ''}
${health.status === 'healthy' ? '✅ All systems operating normally' : ''}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

Generated: ${data.generated_at}
`;

return {
  json: {
    ...data,
    report_text: report
  }
};

